raw:
{
  "summary": [
    {
      "text": "Положение газонефтяного контакта (ГНК) определяют по диаграммам нейтронных методов (НМ). Используют данные повторных замеров в обсаженной скважине или однократных исследований в необсаженной скважине на нефильтрующемся растворе.",
      "claims": [
        "c1",
        "c2"
      ]
    },
    {
      "text": "В обсаженной скважине замеры проводят до стабилизации показаний, что сигнализирует о завершении расформирования зоны проникновения.",
      "claims": [
        "c3"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "Для подсчета запасов критерием водонефтяного контакта (ВНК) принимают значение плотности порового пространства ρп.кр.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "При испытании выше ВНК наблюдается промышленный приток нефти с некоторым количеством воды.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "ГНК устанавливают по диаграммам стационарных нейтронных методов, полученным при повторных замерах в обсаженной скважине.",
      "claims": [
        "c6"
      ]
    },
    {
      "text": "Альтернативно используют данные однократных исследований стационарными или импульсными нейтронными методами в необсаженной скважине.",
      "claims": [
        "c7"
      ]
    },
    {
      "text": "Необсаженная скважина должна быть пробурена на нефильтрующемся буровом растворе.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Повторные замеры в обсаженной скважине проводят по специальной программе до стабилизации повышенных показаний НМ во времени.",
      "claims": [
        "c9"
      ]
    },
    {
      "text": "Стабилизация показаний является признаком завершения расформирования зоны проникновения бурового раствора.",
      "claims": [
        "c10"
      ]
    },
    {
      "text": "Время полного расформирования зоны проникновения тем больше, чем меньше проницаемость коллектора.",
      "claims": [
        "c11"
      ]
    },
    {
      "text": "Время расформирования также увеличивается при большем радиусе зоны проникновения, сформировавшейся к моменту спуска колонны.",
      "claims": [
        "c12"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определить тип скважины: обсаженная или необсаженная.",
      "claims": [
        "c6",
        "c7"
      ]
    },
    {
      "text": "Для необсаженной скважины убедиться, что бурение велось на нефильтрующемся растворе.",
      "claims": [
        "c8"
      ]
    },
    {
      "text": "Провести однократные исследования стационарными или импульсными нейтронными методами (для необсаженной) или повторные замеры (для обсаженной).",
      "claims": [
        "c6",
        "c7",
        "c9"
      ]
    },
    {
      "text": "В обсаженной скважине продолжать замеры до стабилизации повышенных показаний НМ во времени.",
      "claims": [
        "c9",
        "c10"
      ]
    },
    {
      "text": "Определить положение ГНК по диаграммам нейтронных методов в комплексе с данными других геофизических методов.",
      "claims": [
        "c13"
      ]
    }
  ],
  "examples": [
    {
      "title": "Пример определения ГНК по диаграммам НГМ",
      "unit": "u001-02",
      "figure": "рис. 71",
      "condition": [
        {
          "text": "Скважина исследуется в комплексе с данными других геофизических методов.",
          "claims": [
            "c13"
          ]
        }
      ],
      "solution": [
        {
          "text": "Анализируются диаграммы нейтронных методов (НГМ).",
          "claims": [
            "c13"
          ]
        },
        {
          "text": "Идентифицируются зоны: глины, коллекторы, нефть, газ.",
          "claims": [
            "c14"
          ]
        }
      ],
      "result": [
        {
          "text": "Устанавливается положение газонефтяного контакта на основе интерпретации диаграмм.",
          "claims": [
            "c13"
          ]
        }
      ]
    }
  ],
  "numbers": [],
  "formulas": [],
  "misconception": {
    "wrong": "Каротажная кривая — это и есть порода, а не косвенное измерение.",
    "right": [
      {
        "text": "Нейтронные методы дают косвенные показания, требующие интерпретации в комплексе с другими методами.",
        "claims": [
          "c13"
        ]
      },
      {
        "text": "Показания зависят от состояния зоны проникновения, поэтому требуют стабилизации или коррекции.",
        "claims": [
          "c10",
          "c11"
        ]
      }
    ]
  },
  "data_meaning": {
    "input": "Диаграммы нейтронных методов (стационарные или импульсные), данные других геофизических методов.",
    "output": "Положение газонефтяного контакта (ГНК), границы насыщения (глины, коллекторы, нефть, газ).",
    "breaks": [
      {
        "text": "Если зона проникновения не расформировалась полностью, показания будут искажены.",
        "claims": [
          "c10",
          "c11"
        ]
      },
      {
        "text": "В необсаженной скважине на фильтрующемся растворе данные могут быть некорректны.",
        "claims": [
          "c8"
        ]
      }
    ],
    "hypotheses": []
  },
  "analogy": {
    "text": "Процесс стабилизации показаний в обсаженной скважине похож на ожидание сходимости итеративного алгоритма до достижения критерия остановки.",
    "breaks_where": "Аналогия не работает, если «шум» (зона проникновения) не затухает асимптотически, а зависит от физических свойств породы (проницаемости)."
  },
  "now_practice": [],
  "layers": {
    "mechanism": [
      {
        "text": "Нейтронные методы измеряют свойства породы, которые меняются при наличии газа или нефти.",
        "claims": [
          "c6",
          "c7"
        ]
      }
    ],
    "practice": [
      {
        "text": "В обсаженных скважинах необходимо ждать стабилизации сигнала, чтобы исключить влияние бурового раствора.",
        "claims": [
          "c9",
          "c10"
        ]
      }
    ],
    "nuances": [
      {
        "text": "Скорость стабилизации зависит от проницаемости и радиуса зоны проникновения.",
        "claims": [
          "c11",
          "c12"
        ]
      }
    ],
    "deeper": []
  },
  "glossary": [
    {
      "term": "ГНК",
      "en": "Gas-Oil Contact",
      "definition": "Граница раздела между газовой и нефтяной зонами в пласте."
    },
    {
      "term": "НМ",
      "en": "Neutron Methods",
      "definition": "Геофизические методы, основанные на взаимодействии нейтронов с ядрами атомов породы."
    }]}
